#!/bin/sh
# The Swift bindings of the core's native interface (src/lib.rs), generated by UniFFI into apps/mac and not kept in
# git: the Swift types and functions into the Shell module (Sources/Shell/CoreBindings.swift), their C header beside
# the module map (Sources/GPCoreFFI/gp_core_ffi.h). A file is written only when it changed, so Swift rebuilds no more
# than it must. crates/gp-core/build.sh (the Mac) and apps/mac/apple.sh (iOS) run it before building the app.
set -e
cd "$(dirname "$0")/../.."
MAC=apps/mac/Sources
# uniffi-bindgen reads the interface from a library's metadata: a dynamic one for this machine, unoptimised (fast).
cargo rustc --quiet -p gp-core-ffi --lib --crate-type cdylib
OUT=$(mktemp -d)
trap 'rm -rf "$OUT"' EXIT
cargo run --quiet -p gp-core-ffi --features bindgen --bin uniffi-bindgen -- \
  generate --library target/debug/libgp_core_ffi.dylib --language swift --out-dir "$OUT" >/dev/null
cmp -s "$OUT/Shell.swift" "$MAC/Shell/CoreBindings.swift" || cp "$OUT/Shell.swift" "$MAC/Shell/CoreBindings.swift"
cmp -s "$OUT/gp_core_ffi.h" "$MAC/GPCoreFFI/gp_core_ffi.h" || cp "$OUT/gp_core_ffi.h" "$MAC/GPCoreFFI/gp_core_ffi.h"
